CREATE TABLE IF NOT EXISTS public.driver_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, driver_id uuid REFERENCES public.drivers(id) ON DELETE CASCADE, guarantor_id uuid REFERENCES public.guarantors(id) ON DELETE CASCADE, document_type text NOT NULL, document_number text, file_path text, file_name text, mime_type text, expires_at date, verification_status text NOT NULL DEFAULT 'PENDING', verified_at timestamptz, verified_by uuid, notes text, created_at timestamptz NOT NULL DEFAULT now(), CHECK (driver_id IS NOT NULL OR guarantor_id IS NOT NULL));